public class Main {
    public static void main(String[] args) {
        Node ana = new Node("Ana");
        Node ben = new Node("Ben");
        Node cy = new Node("Cy");
        ana.next = ben;
        ben.next = cy;
        cy.next = ana; // the last player points back to the first

        Node turn = ana;
        for (int i = 1; i <= 6; i++) {
            System.out.println("Turn " + i + ": " + turn.name);
            turn = turn.next;
        }
    }
}

class Node {
    String name;
    Node next;

    Node(String name) {
        this.name = name;
    }
}
